-- Medina Ziyarat batch: stops #3–#5 (Uhud, Aliya Date Garden, Al-Baqi).
-- Coordinates are stored explicitly so MapKit never resolves a free-text place name.

INSERT OR REPLACE INTO ziyarat_places (
  id, route_id, slug, title, title_ar, category, short_description, long_description,
  interesting_facts_json, visit_notes, visit_type, duration_minutes, latitude, longitude,
  address, map_label, route_order, status, created_by, created_at, updated_at
) VALUES (
  'mount-uhud', 'medina-main', 'mount-uhud', 'Mount Uhud', 'جبل أُحد', 'mountain', 'A major historic landmark north of Madinah, where the Battle of Uhud took place in 3 AH.', 'Mount Uhud is one of Madinah’s best-known natural and historical landmarks. It extends for about seven kilometers north of the Prophet’s Mosque and reaches about 1,077 meters above sea level. At its foothills the Battle of Uhud took place in 3 AH (625 CE), during which 70 companions were martyred. For the journey map, iumrah uses the visitor area at the Uhud battlefield near the southwestern foothills, close to Jabal al-Rumah and the Martyrs’ Cemetery, rather than an arbitrary point in the middle of the mountain.', '["Mount Uhud extends for about 7 km and is roughly 2–3 km wide.","The Battle of Uhud took place at its foothills in 3 AH (625 CE).","Jabal al-Rumah and the Uhud Martyrs’ Cemetery are part of the same historic landscape."]', 'Historical stop. Plan about 30–45 minutes. The route point is at the visitor area by the foothills; climbing the mountain is not part of this stop. Follow the guide and current local directions.', 'stop', 40, 24.50295, 39.61132, 'Uhud Battle Site, Sayyid al-Shuhada, Madinah, Saudi Arabia', 'Mount Uhud · Uhud visitor area', 3, 'published', 'seed', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
);

