INSERT OR REPLACE INTO ziyarat_place_translations (
  place_id, locale, title, short_description, long_description,
  interesting_facts_json, visit_notes, created_at, updated_at
) VALUES
(
  'mount-uhud', 'ru', 'Гора Ухуд', 'Один из главных исторических символов Медины — у подножия Ухуда в 3 году хиджры произошла битва при Ухуде.', 'Гора Ухуд — одна из самых известных природных и исторических достопримечательностей Медины. Она тянется примерно на семь километров к северу от Мечети Пророка и достигает около 1 077 м над уровнем моря. У её подножия в 3 году хиджры (625 г.) произошла битва при Ухуде, в которой погибли 70 сподвижников. Для карты iumrah используется реальная зона посещения у исторического поля битвы на юго-западном подножии, рядом с Джабаль ар-Рума и кладбищем шахидов, а не случайная точка в центре горного массива.', '["Ухуд тянется примерно на 7 км, его ширина составляет около 2–3 км.","Битва при Ухуде произошла у подножия горы в 3 году хиджры (625 г.).","Рядом находятся Джабаль ар-Рума и кладбище шахидов Ухуда — части одного исторического ландшафта."]', 'Историческая остановка примерно на 30–45 минут. Точка маршрута находится в зоне посещения у подножия; подъём на гору в эту остановку не входит. Следуйте указаниям гида и действующим местным правилам.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'mount-uhud', 'uz', 'Uhud tog‘i', 'Madinaning eng muhim tarixiy ramzlaridan biri — Uhud jangi hijriy 3-yilda shu tog‘ etagida bo‘lib o‘tgan.', 'Uhud tog‘i Madinaning eng mashhur tabiiy va tarixiy maskanlaridan biridir. U Payg‘ambar masjididan shimolda taxminan yetti kilometrga cho‘ziladi va dengiz sathidan qariyb 1 077 metr balandlikka yetadi. Hijriy 3-yilda (milodiy 625-yil) uning etagida Uhud jangi bo‘lib o‘tgan va unda 70 nafar sahoba shahid bo‘lgan. iumrah xaritasida tog‘ning o‘rtasidagi tasodifiy nuqta emas, balki janubi-g‘arbiy etakdagi Uhud jang maydoni, Jabal ar-Rumah va shahidlar qabristoniga yaqin haqiqiy tashrif hududi ishlatiladi.', '["Uhud tog‘i taxminan 7 km uzunlikda va 2–3 km kenglikda.","Uhud jangi hijriy 3-yilda (625-yil) tog‘ etagida bo‘lib o‘tgan.","Jabal ar-Rumah va Uhud shahidlari qabristoni shu tarixiy hududning bir qismidir."]', 'Tarixiy to‘xtash joyi, odatda 30–45 daqiqa. Yo‘nalish nuqtasi tog‘ etagidagi tashrif hududida; tog‘ga chiqish bu to‘xtash dasturiga kirmaydi. Gid va amaldagi mahalliy ko‘rsatmalarga rioya qiling.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'mount-uhud', 'uz-cyrl', 'Уҳуд тоғи', 'Мадинанинг энг муҳим тарихий рамзларидан бири — Уҳуд жанги ҳижрий 3-йилда шу тоғ этагида бўлиб ўтган.', 'Уҳуд тоғи Мадинанинг энг машҳур табиий ва тарихий масканларидан биридир. У Пайғамбар масжидидан шимолда тахминан етти километрга чўзилади ва денгиз сатҳидан қарийб 1 077 метр баландликка етади. Ҳижрий 3-йилда (милодий 625-йил) унинг этагида Уҳуд жанги бўлиб ўтган ва унда 70 нафар саҳоба шаҳид бўлган. iumrah харитасида тоғнинг ўртасидаги тасодифий нуқта эмас, балки жануби-ғарбий этакдаги Уҳуд жанг майдони, Жабал ар-Румаҳ ва шаҳидлар қабристонига яқин ҳақиқий ташриф ҳудуди ишлатилади.', '["Уҳуд тоғи тахминан 7 км узунликда ва 2–3 км кенгликда.","Уҳуд жанги ҳижрий 3-йилда (625-йил) тоғ этагида бўлиб ўтган.","Жабал ар-Румаҳ ва Уҳуд шаҳидлари қабристони шу тарихий ҳудуднинг бир қисмидир."]', 'Тарихий тўхташ жойи, одатда 30–45 дақиқа. Йўналиш нуқтаси тоғ этагидаги ташриф ҳудудида; тоғга чиқиш бу тўхташ дастурига кирмайди. Гид ва амалдаги маҳаллий кўрсатмаларга риоя қилинг.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'mount-uhud', 'en', 'Mount Uhud', 'A major historic landmark north of Madinah, where the Battle of Uhud took place in 3 AH.', 'Mount Uhud is one of Madinah’s best-known natural and historical landmarks. It extends for about seven kilometers north of the Prophet’s Mosque and reaches about 1,077 meters above sea level. At its foothills the Battle of Uhud took place in 3 AH (625 CE), during which 70 companions were martyred. For the journey map, iumrah uses the visitor area at the Uhud battlefield near the southwestern foothills, close to Jabal al-Rumah and the Martyrs’ Cemetery, rather than an arbitrary point in the middle of the mountain.', '["Mount Uhud extends for about 7 km and is roughly 2–3 km wide.","The Battle of Uhud took place at its foothills in 3 AH (625 CE).","Jabal al-Rumah and the Uhud Martyrs’ Cemetery are part of the same historic landscape."]', 'Historical stop. Plan about 30–45 minutes. The route point is at the visitor area by the foothills; climbing the mountain is not part of this stop. Follow the guide and current local directions.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
);

INSERT OR REPLACE INTO ziyarat_places (
  id, route_id, slug, title, title_ar, category, short_description, long_description,
  interesting_facts_json, visit_notes, visit_type, duration_minutes, latitude, longitude,
  address, map_label, route_order, status, created_by, created_at, updated_at
) VALUES (
  'aliya-date-garden', 'medina-main', 'aliya-date-garden', 'Aliya Date Garden', 'مزارع عالية المدينة', 'garden', 'A palm garden in Qurban that shows the agricultural side of Madinah and its long tradition of date cultivation.', 'Aliya Date Garden is a concrete visitor point within the palm-growing landscape of southern Madinah. The wider Aliat Al-Madinah farming zone is known for dense date palms, traditional irrigation channels and date production, and Madinah’s official tourism site describes these farms as an important historical agricultural area. iumrah stores the exact Aliya Date Garden coordinate in Qurban so the route opens the intended garden instead of resolving to a random farm.', '["The Al-Aliyah area is one of Madinah’s best-known historic agricultural zones.","Dense palm groves and irrigation channels are characteristic of the farming landscape.","Madinah is famous for many local date varieties, including Ajwa."]', 'Short garden stop, usually about 20–30 minutes. Access and opening conditions can vary, so follow the guide’s current meeting point and instructions before entering or purchasing dates.', 'stop', 25, 24.449811, 39.627519, 'Qurban, Madinah 42316, Saudi Arabia', 'Aliya Date Garden · exact point', 4, 'published', 'seed', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
);

