INSERT OR REPLACE INTO ziyarat_place_translations (
  place_id, locale, title, short_description, long_description,
  interesting_facts_json, visit_notes, created_at, updated_at
) VALUES
(
  'aliya-date-garden', 'ru', 'Финиковый сад Алия', 'Пальмовый сад в районе Курбан, показывающий сельскохозяйственную сторону Медины и её многовековую традицию выращивания фиников.', 'Aliya Date Garden — конкретная точка посещения среди пальмовых хозяйств южной Медины. Более широкий район ферм Аль-Алия известен густыми финиковыми пальмами, оросительными каналами и производством фиников; официальный туристический портал Медины относит эти фермы к важным историческим сельскохозяйственным зонам города. iumrah сохраняет точные координаты сада в районе Курбан, поэтому маршрут открывает нужное место, а не случайную ферму поблизости.', '["Район Аль-Алия — одна из известных исторических сельскохозяйственных зон Медины.","Для местного ландшафта характерны густые пальмовые рощи и оросительные каналы.","Медина известна многими сортами фиников, в том числе аджва."]', 'Короткая остановка примерно на 20–30 минут. Доступ и режим работы могут меняться, поэтому ориентируйтесь на актуальную точку встречи и указания гида перед входом или покупкой фиников.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'aliya-date-garden', 'uz', 'Aliya xurmo bog‘i', 'Qurban hududidagi xurmo bog‘i — Madinaning dehqonchilik muhiti va qadimiy xurmo yetishtirish an’anasini ko‘rsatadi.', 'Aliya Date Garden Madinaning janubidagi xurmo xo‘jaliklari orasidagi aniq tashrif nuqtasidir. Kengroq Al-Aliya dehqonchilik hududi zich xurmozorlar, sug‘orish ariqlari va xurmo yetishtirish bilan mashhur; Madinaning rasmiy turizm sayti bu fermalarni shaharning muhim tarixiy qishloq xo‘jaligi hududlaridan biri sifatida tasvirlaydi. iumrah Qurban hududidagi Aliya Date Garden koordinatasini aniq saqlaydi, shuning uchun xarita tasodifiy boshqa fermani emas, kerakli bog‘ni ochadi.', '["Al-Aliya Madinaning mashhur tarixiy dehqonchilik hududlaridan biridir.","Zich xurmozorlar va sug‘orish kanallari bu hudud manzarasining muhim qismidir.","Madina ko‘plab mahalliy xurmo navlari, jumladan Ajva bilan mashhur."]', 'Qisqa bog‘ to‘xtashi, odatda 20–30 daqiqa. Kirish va ish vaqti o‘zgarishi mumkin, shuning uchun bog‘ga kirish yoki xurmo xarid qilishdan oldin gidning joriy uchrashuv nuqtasi va ko‘rsatmalariga amal qiling.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'aliya-date-garden', 'uz-cyrl', 'Алия хурмо боғи', 'Қурбан ҳудудидаги хурмо боғи — Мадинанинг деҳқончилик муҳити ва қадимий хурмо етиштириш анъанасини кўрсатади.', 'Aliya Date Garden Мадинанинг жанубидаги хурмо хўжаликлари орасидаги аниқ ташриф нуқтасидир. Кенгроқ Ал-Алия деҳқончилик ҳудуди зич хурмозорлар, суғориш ариқлари ва хурмо етиштириш билан машҳур; Мадинанинг расмий туризм сайти бу фермаларни шаҳарнинг муҳим тарихий қишлоқ хўжалиги ҳудудларидан бири сифатида тасвирлайди. iumrah Қурбан ҳудудидаги Aliya Date Garden координатасини аниқ сақлайди, шунинг учун харита тасодифий бошқа фермани эмас, керакли боғни очади.', '["Ал-Алия Мадинанинг машҳур тарихий деҳқончилик ҳудудларидан биридир.","Зич хурмозорлар ва суғориш каналлари бу ҳудуд манзарасининг муҳим қисмидир.","Мадина кўплаб маҳаллий хурмо навлари, жумладан Ажва билан машҳур."]', 'Қисқа боғ тўхташи, одатда 20–30 дақиқа. Кириш ва иш вақти ўзгариши мумкин, шунинг учун боғга кириш ёки хурмо харид қилишдан олдин гиднинг жорий учрашув нуқтаси ва кўрсатмаларига амал қилинг.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'aliya-date-garden', 'en', 'Aliya Date Garden', 'A palm garden in Qurban that shows the agricultural side of Madinah and its long tradition of date cultivation.', 'Aliya Date Garden is a concrete visitor point within the palm-growing landscape of southern Madinah. The wider Aliat Al-Madinah farming zone is known for dense date palms, traditional irrigation channels and date production, and Madinah’s official tourism site describes these farms as an important historical agricultural area. iumrah stores the exact Aliya Date Garden coordinate in Qurban so the route opens the intended garden instead of resolving to a random farm.', '["The Al-Aliyah area is one of Madinah’s best-known historic agricultural zones.","Dense palm groves and irrigation channels are characteristic of the farming landscape.","Madinah is famous for many local date varieties, including Ajwa."]', 'Short garden stop, usually about 20–30 minutes. Access and opening conditions can vary, so follow the guide’s current meeting point and instructions before entering or purchasing dates.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
);

INSERT OR REPLACE INTO ziyarat_places (
  id, route_id, slug, title, title_ar, category, short_description, long_description,
  interesting_facts_json, visit_notes, visit_type, duration_minutes, latitude, longitude,
  address, map_label, route_order, status, created_by, created_at, updated_at
) VALUES (
  'al-baqi', 'medina-main', 'al-baqi', 'Al-Baqi Cemetery', 'مقبرة البقيع', 'cemetery', 'The historic cemetery immediately southeast of the Prophet’s Mosque, where many relatives, companions and early Muslims are buried.', 'Al-Baqi, also known as Baqi al-Gharqad, is the historic cemetery beside the Prophet’s Mosque and has been used since the earliest Muslim community in Madinah. Many members of the Prophet’s ﷺ family, companions and other prominent early Muslims are buried here. Today the cemetery is characterized by simple grave markers. Access arrangements can change, so iumrah uses the exact cemetery coordinate for map context while the live guide directs the group to the currently permitted visitor area.', '["Al-Baqi lies immediately southeast of the Prophet’s Mosque.","The cemetery dates to the earliest Islamic period in Madinah, around 622 CE.","Many members of the Prophet’s ﷺ family, companions and notable early Muslims are buried here."]', 'A quiet and respectful stop, usually about 20–30 minutes. Access rules and visiting times can change; follow current local instructions and the guide’s directions. Entry is not guaranteed as part of the route.', 'stop', 25, 24.46667, 39.61633, 'Al-Baqi Cemetery, Madinah, Saudi Arabia', 'Al-Baqi Cemetery · exact point', 5, 'published', 'seed', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
);

