INSERT OR REPLACE INTO ziyarat_place_translations (
  place_id, locale, title, short_description, long_description,
  interesting_facts_json, visit_notes, created_at, updated_at
) VALUES
(
  'al-baqi', 'ru', 'Кладбище Аль-Баки', 'Историческое кладбище сразу к юго-востоку от Мечети Пророка, где похоронены многие родственники Пророка ﷺ, сподвижники и первые мусульмане.', 'Аль-Баки, также известное как Баки аль-Гаркад, — историческое кладбище рядом с Мечетью Пророка, используемое со времени ранней мусульманской общины Медины. Здесь похоронены многие члены семьи Пророка ﷺ, сподвижники и другие известные мусульмане первых поколений. Сегодня кладбище отличается простыми обозначениями могил. Порядок доступа может меняться, поэтому iumrah сохраняет точную координату самого кладбища для карты, а живой гид направляет группу к разрешённой на данный момент зоне посещения.', '["Аль-Баки находится непосредственно к юго-востоку от Мечети Пророка.","Кладбище относится к самому раннему исламскому периоду Медины — примерно с 622 года.","Здесь похоронены многие родственники Пророка ﷺ, сподвижники и известные мусульмане первых поколений."]', 'Спокойная и уважительная остановка примерно на 20–30 минут. Правила доступа и часы посещения могут меняться; следуйте действующим местным указаниям и инструкциям гида. Вход внутрь не гарантируется программой маршрута.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'al-baqi', 'uz', 'Al-Baqi qabristoni', 'Payg‘ambar masjidining janubi-sharqida joylashgan tarixiy qabriston; bu yerda Payg‘ambarimiz ﷺning ko‘plab qarindoshlari, sahobalar va ilk musulmonlar dafn etilgan.', 'Al-Baqi, Baqi al-Gharqad nomi bilan ham tanilgan, Payg‘ambar masjidi yonidagi tarixiy qabriston bo‘lib, Madinadagi ilk musulmon jamoasi davridan beri foydalanib kelinadi. Bu yerda Payg‘ambarimiz ﷺning ko‘plab oila a’zolari, sahobalar va ilk avlodlarning mashhur musulmonlari dafn etilgan. Bugungi qabristonda qabrlar oddiy belgilar bilan ko‘rsatiladi. Kirish tartibi o‘zgarishi mumkin, shu sabab iumrah xaritada qabristonning aniq koordinatasini saqlaydi, jonli gid esa guruhni ayni paytda ruxsat etilgan tashrif hududiga yo‘naltiradi.', '["Al-Baqi Payg‘ambar masjidining darhol janubi-sharqida joylashgan.","Qabriston Madinadagi eng ilk Islom davriga, taxminan 622-yilga borib taqaladi.","Bu yerda Payg‘ambarimiz ﷺning ko‘plab qarindoshlari, sahobalar va mashhur ilk musulmonlar dafn etilgan."]', 'Tinch va hurmat bilan o‘tiladigan to‘xtash, odatda 20–30 daqiqa. Kirish qoidalari va tashrif vaqtlari o‘zgarishi mumkin; joriy mahalliy ko‘rsatmalar va gid yo‘riqlariga rioya qiling. Yo‘nalish doirasida ichkariga kirish kafolatlanmaydi.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'al-baqi', 'uz-cyrl', 'Ал-Бақи қабристони', 'Пайғамбар масжидининг жануби-шарқида жойлашган тарихий қабристон; бу ерда Пайғамбаримиз ﷺнинг кўплаб қариндошлари, саҳобалар ва илк мусулмонлар дафн этилган.', 'Ал-Бақи, Бақи ал-Ғарқад номи билан ҳам танилган, Пайғамбар масжиди ёнидаги тарихий қабристон бўлиб, Мадинадаги илк мусулмон жамоаси давридан бери фойдаланиб келинади. Бу ерда Пайғамбаримиз ﷺнинг кўплаб оила аъзолари, саҳобалар ва илк авлодларнинг машҳур мусулмонлари дафн этилган. Бугунги қабристонда қабрлар оддий белгилар билан кўрсатилади. Кириш тартиби ўзгариши мумкин, шу сабаб iumrah харитада қабристоннинг аниқ координатасини сақлайди, жонли гид эса гуруҳни айни пайтда рухсат этилган ташриф ҳудудига йўналтиради.', '["Ал-Бақи Пайғамбар масжидининг дарҳол жануби-шарқида жойлашган.","Қабристон Мадинадаги энг илк Ислом даврига, тахминан 622-йилга бориб тақалади.","Бу ерда Пайғамбаримиз ﷺнинг кўплаб қариндошлари, саҳобалар ва машҳур илк мусулмонлар дафн этилган."]', 'Тинч ва ҳурмат билан ўтиладиган тўхташ, одатда 20–30 дақиқа. Кириш қоидалари ва ташриф вақтлари ўзгариши мумкин; жорий маҳаллий кўрсатмалар ва гид йўриқларига риоя қилинг. Йўналиш доирасида ичкарига кириш кафолатланмайди.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
),
(
  'al-baqi', 'en', 'Al-Baqi Cemetery', 'The historic cemetery immediately southeast of the Prophet’s Mosque, where many relatives, companions and early Muslims are buried.', 'Al-Baqi, also known as Baqi al-Gharqad, is the historic cemetery beside the Prophet’s Mosque and has been used since the earliest Muslim community in Madinah. Many members of the Prophet’s ﷺ family, companions and other prominent early Muslims are buried here. Today the cemetery is characterized by simple grave markers. Access arrangements can change, so iumrah uses the exact cemetery coordinate for map context while the live guide directs the group to the currently permitted visitor area.', '["Al-Baqi lies immediately southeast of the Prophet’s Mosque.","The cemetery dates to the earliest Islamic period in Madinah, around 622 CE.","Many members of the Prophet’s ﷺ family, companions and notable early Muslims are buried here."]', 'A quiet and respectful stop, usually about 20–30 minutes. Access rules and visiting times can change; follow current local instructions and the guide’s directions. Entry is not guaranteed as part of the route.', '2026-09-09T13:30:00.000Z', '2026-09-09T13:30:00.000Z'
);
